-- 00_diagnose.sql  (read-only) : shows which enum types and tables from files 01-07 are still missing in this database.
-- Run it in the SQL Editor. An empty result means 01-07 are all in place.
with expected_types(name) as (values ('agreement_status'), ('applicability'), ('approval_decision'), ('approval_entity'), ('approval_lane'), ('app_role'), ('assignment_status'), ('clock_status'), ('clock_type'), ('compliance_status'), ('consent_channel'), ('consent_purpose'), ('contact_channel'), ('contact_outcome'), ('cost_bearer'), ('credit_result'), ('customer_type'), ('dispatch_status'), ('dnd_status'), ('document_bucket'), ('einvoice_state'), ('feasibility_status'), ('followup_kind'), ('followup_status'), ('gate'), ('installation_status'), ('lead_source'), ('lead_status'), ('loan_rejection_code'), ('loan_status'), ('lock_status'), ('message_channel'), ('message_purpose'), ('message_status'), ('notification_severity'), ('opportunity_stage'), ('party_status'), ('payment_kind'), ('payment_mode'), ('phase'), ('pi_status'), ('portal_status'), ('quote_status'), ('receivable_status'), ('roof_ownership'), ('roof_type'), ('rule_confidence'), ('rule_status'), ('scheme_route'), ('security_type'), ('segment'), ('serial_status'), ('severity'), ('site_category'), ('sku_category'), ('sop_stage'), ('so_status'), ('subsidy_cohort'), ('subsidy_rejection_reason'), ('subsidy_status'), ('survey_status'), ('temperature'), ('template_category'), ('timeline_bucket'), ('vendor_level'), ('warranty_status'), ('warranty_type')),
expected_tables(file, name) as (values ('02','organizations'), ('02','discoms'), ('02','territories'), ('02','distributors'), ('02','dealers'), ('02','profiles'), ('02','user_territories'), ('02','pincodes'), ('02','vendor_registrations'), ('02','sop_cases'), ('02','distributor_score_history'), ('03','leads'), ('03','lead_consents'), ('03','lead_events'), ('03','lead_assignments'), ('03','followups'), ('03','contact_logs'), ('03','dnd_register'), ('03','lead_scores'), ('03','source_api_keys'), ('03','customers'), ('03','sites'), ('03','site_surveys'), ('04','opportunities'), ('04','requirement_forms'), ('04','segment_form_config'), ('04','negotiation_logs'), ('04','skus'), ('04','sku_compliance'), ('04','sku_prices'), ('04','stock_batches'), ('04','inventory_serials'), ('05','documents'), ('05','quotations'), ('05','quotation_lines'), ('05','quote_discussions'), ('05','approval_rules'), ('05','approvals'), ('05','proforma_invoices'), ('05','proforma_invoice_lines'), ('05','sales_orders'), ('05','sales_order_lines'), ('05','payments'), ('05','credit_checks'), ('05','credit_overrides'), ('05','dispatches'), ('05','dispatch_serials'), ('05','einvoice_status'), ('06','loans'), ('06','installations'), ('06','discom_applications'), ('06','subsidy_claims'), ('06','warranty_tickets'), ('06','dealer_receivables'), ('07','rule_config'), ('07','clocks'), ('07','notifications'), ('07','message_templates'), ('07','message_log'), ('07','kpi_snapshots'), ('07','audit_log'), ('07','compliance_calendar_items'), ('07','job_runs'), ('07','verify_register'), ('07','gate_applicability'), ('07','breach_incidents'), ('07','data_requests'))
select 'missing enum type' as problem, name as item, '01' as file from expected_types where not exists (select 1 from pg_type t join pg_namespace n on n.oid = t.typnamespace where n.nspname = 'public' and t.typname = expected_types.name)
union all
select 'missing table', name, file from expected_tables where not exists (select 1 from pg_tables where schemaname = 'public' and tablename = expected_tables.name)
order by 1, 3, 2;
